export function AnnouncementBar({
  message = "{{message}}",
  ctaText = "{{ctaText}}",
  bg = "{{bg}}",
  align = "{{align}}",
  dismissible = {{dismissible}},
}) {
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: align === "center" ? "center" : "flex-start",
      textAlign: align, gap: 12, padding: "10px 18px", font: "14px/1.4 system-ui, sans-serif", color: "#FAF7F2", background: bg }}>
      <p style={{ margin: 0 }}>{message} <a href="#" style={{ color: "inherit", textDecoration: "underline", fontWeight: 600, marginLeft: 6 }}>{ctaText}</a></p>
      {dismissible && (
        <button type="button" aria-label="Dismiss announcement" style={{ background: "none", border: "none",
          color: "inherit", fontSize: 18, lineHeight: 1, cursor: "pointer", padding: "0 4px" }}>
          &times;
        </button>
      )}
    </div>
  );
}
